package com.medcore.backend.api.enfermeria;import jakarta.validation.Valid;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController public class ObservacionController{private final ObservacionService service;public ObservacionController(ObservacionService service){this.service=service;}@PostMapping("/api/internaciones/{id}/observaciones")@PreAuthorize("hasRole('ENFERMERIA')")public ResponseEntity<ObservacionResponse>crear(@PathVariable Long id,@Valid@RequestBody ObservacionRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.crear(id,r));}@GetMapping("/api/internaciones/{id}/observaciones")@PreAuthorize("hasAnyRole('ADMIN','MEDICO','ENFERMERIA')")public Page<ObservacionResponse>listar(@PathVariable Long id,@PageableDefault(size=20,sort="fechaHora")Pageable p){return service.listar(id,p);}}
